<section class="module-hero"><div><span class="module-kicker">Ticket <?= htmlspecialchars($ticket['reference']) ?></span><h1><?= htmlspecialchars($ticket['subject']) ?></h1><p><?= htmlspecialchars($ticket['user_name']??'Utilisateur') ?> · <?= htmlspecialchars($ticket['user_email']??'') ?> · <?= htmlspecialchars($ticket['user_phone']??'') ?></p></div><a class="btn secondary" href="/admin/tickets">← Tous les tickets</a></section>
<div class="module-two"><section class="module-panel"><h2>Conversation</h2><div class="ticket-thread"><?php foreach($messages as $m): ?><div class="ticket-message <?= $m['sender_role']==='staff'?'staff':'' ?>"><strong><?= htmlspecialchars($m['name']??($m['sender_role']==='staff'?'IFMAP':'Utilisateur')) ?></strong><div><?= nl2br(htmlspecialchars($m['message'])) ?></div><small><?= htmlspecialchars($m['created_at']) ?></small></div><?php endforeach ?></div></section>
<section class="module-panel"><h2>Répondre & traiter</h2><form class="module-form" method="post" action="/admin/ticket"><input type="hidden" name="ticket_id" value="<?= (int)$ticket['id'] ?>"><label>Statut<select name="status"><?php foreach(['open'=>'Ouvert','in_progress'=>'En traitement','waiting_user'=>'En attente utilisateur','resolved'=>'Résolu','closed'=>'Fermé'] as $v=>$l): ?><option value="<?= $v ?>" <?= $ticket['status']===$v?'selected':'' ?>><?= $l ?></option><?php endforeach ?></select></label><label>Réponse<textarea name="message" placeholder="Votre réponse à l’utilisateur..."></textarea></label><button class="btn primary">Enregistrer et répondre</button></form></section></div>
